# Contenu des pages conducteur et demande. Les réponses et critères restent à valider avant publication.
F=lambda n,l,t='text',rq=True,x='':f'<div class="fd"><label for="{n}">{l}{"" if rq else " <small>(facultatif)</small>"}</label><input id="{n}" name="{n}" type="{t}" {"required" if rq else ""} {x}><p class="er" id="{n}-e"></p></div>'
CON='<div class="fd ck"><label><input type="checkbox" name="consent" required> <span>J\'accepte que ROAM utilise ces informations pour me recontacter. <a href="../../premium-v2/confidentialite/">Données personnelles</a></span></label><p class="er" id="consent-e"></p></div><input class="hp" name="website" tabindex="-1" autocomplete="off" aria-hidden="true">'
ST='<p class="st" role="status" data-st></p>'
STEPS=[('Inscription','Vous remplissez le formulaire en deux minutes.'),('Vérification','Nous regardons votre profil et votre voiture.'),('Sélection','Si une campagne correspond à votre zone, nous vous contactons.'),('Pose','Le covering est posé par des professionnels.'),('Circulation','Vous roulez selon les conditions convenues.'),('Validation et rémunération','Les critères sont contrôlés, puis vous êtes rémunéré selon le contrat.')]
FAQ=[('Est-ce que le covering abîme la voiture ?','Un film posé et retiré dans de bonnes conditions protège généralement la peinture. L\'état de votre carrosserie sera vérifié avant la pose.'),
     ('Qui s\'occupe de la pose et du retrait ?','ROAM organise la pose et le retrait avec des professionnels, aux conditions prévues dans le contrat.'),
     ('Que se passe-t-il pour mon assurance ?','Les démarches éventuelles seront précisées avant la signature. Votre situation sera regardée au cas par cas.'),
     ('Quelles sont mes obligations ?','Garder la voiture en bon état, rouler selon les conditions convenues et valider vos kilomètres dans l\'application.'),
     ('Mon trajet est-il suivi en détail ?','Non, le principe est de valider des kilomètres et de grandes zones, pas chacun de vos trajets. La méthode exacte sera précisée dans le contrat.'),
     ('Suis-je sûr d\'avoir une campagne ?','Non. La candidature vous inscrit sur notre liste de conducteurs intéressés. Une campagne dépend de votre zone, de votre voiture et des besoins des annonceurs.')]
CRIT=[('Votre voiture','Modèle, année et kilométrage'),('Son état','Carrosserie propre, sans dégâts importants'),('Votre zone','Les villes et secteurs où vous roulez'),('Votre usage','Votre rythme de déplacement au quotidien')]
BTNC='<a class="btn" href="#candidature"><span class="rl" data-t="Déposer ma candidature">Déposer ma candidature</span></a>'
D=f'''<section class="dh" aria-label="Présentation"><h1><span class="ln"><span>Votre voiture roule déjà.</span></span><span class="ln"><span>Faites-la travailler.</span></span></h1><div class="art"><img src="../img/s_b1.webp" alt="Berline habillée en noir et blanc" width="2200" height="1238"></div><div class="foot"><p>Acceptez une publicité sur votre voiture et recevez une rémunération, selon les conditions du programme.</p>{BTNC}</div></section>
<section class="cvw" aria-labelledby="cv-t"><div class="cvs"><div class="cvt"><p class="eye">Le principe</p><h2 class="big" id="cv-t">Un film posé sur votre carrosserie</h2><p class="lead2">Nous nous occupons du visuel et de la pose. Vous continuez à rouler comme d'habitude.</p></div><div class="cvc"><img src="../img/s_a1.webp" alt="La même voiture, blanche, avant la pose" width="2200" height="1238"><img class="top" src="../img/s_b1.webp" alt="La voiture après la pose du covering" width="2200" height="1238"><i class="sq"></i></div></div></section>
<section class="stp" aria-labelledby="st-t"><div class="stl"><p class="eye">Comment ça marche</p><h2 class="big" id="st-t">Six étapes, du formulaire à la route</h2><ol class="tl">{''.join(f'<li><span>{i+1}</span><div><h3>{t}</h3><p>{d}</p></div></li>' for i,(t,d) in enumerate(STEPS))}</ol></div><div class="stm" aria-hidden="true"><svg viewBox="0 0 256 210"><path class="be" d="{MAP}"/><path class="rt" d="M60 40C90 90 110 40 130 74S170 70 200 96 150 130 128 116"/><circle class="pt" r="5"/></svg></div></section>
<section class="sim" aria-labelledby="si-t"><div class="sh2"><p class="eye">Combien peut-on gagner ?</p><h2 class="big" id="si-t">Une estimation, pas une promesse</h2><p class="lead2">Votre revenu dépend de la voiture, de la zone, de la campagne, des kilomètres éligibles et du contrat. Essayez plusieurs scénarios.</p></div>
<form class="sf" onsubmit="return false"><fieldset><legend>Votre zone</legend><div class="op"><label><input type="radio" name="z" value="1"><span>Zone rurale</span></label><label><input type="radio" name="z" value="2" checked><span>Périphérie</span></label><label><input type="radio" name="z" value="3"><span>Grande ville</span></label></div></fieldset>
<fieldset><legend>Format de campagne</legend><div class="op"><label><input type="radio" name="f" value="1"><span>Classique</span></label><label><input type="radio" name="f" value="2" checked><span>Medium</span></label><label><input type="radio" name="f" value="3"><span>Complet</span></label></div></fieldset>
<div class="rg"><label for="simkm">Kilomètres par mois <output id="kmo" for="simkm">1 000 km</output></label><input id="simkm" type="range" min="200" max="3000" step="100" value="1000"></div>
<div class="res" aria-live="polite"><p class="rl2">Niveau indicatif</p><strong id="lvl">Moyen</strong><div class="bar2"><i id="gau"></i></div><p class="amt" id="amt">Montant : à définir avant publication</p><p class="fine">Estimation indicative, jamais garantie. Aucune rémunération sans campagne et contrat signé.</p></div></form></section>
<section class="veh" aria-labelledby="ve-t"><p class="eye">Quels véhicules ?</p><h2 class="big" id="ve-t">Ce que nous regardons</h2><ul class="crit">{''.join(f'<li><b>{a}</b><span>{b}</span></li>' for a,b in CRIT)}</ul><p class="fine">Les critères définitifs seront précisés pendant la candidature.</p></section>
<section class="faq" aria-labelledby="fa-t"><p class="eye">Vos questions</p><h2 class="big" id="fa-t">Avant de vous lancer</h2><div class="fql">{''.join(f'<details><summary>{q}</summary><p>{a}</p></details>' for q,a in FAQ)}</div></section>
<section class="cand" id="candidature" aria-labelledby="ca-t"><div class="cah"><p class="eye">Candidature</p><h2 class="big" id="ca-t">Rejoignez la liste des conducteurs</h2><p class="lead2">Une candidature ne garantit pas une campagne immédiate. Nous vous recontactons si une campagne correspond à votre zone et à votre voiture.</p></div>
<form class="fm" data-form="driverEndpoint" novalidate><div class="g2">{F('name','Nom et prénom')}{F('email','E-mail','email')}{F('phone','Téléphone','tel')}{F('city','Ville ou région')}{F('car','Marque et modèle du véhicule')}{F('year','Année du véhicule','number',True,'min="1990" max="2027" inputmode="numeric"')}{F('km','Kilométrage approximatif','number',True,'min="0" inputmode="numeric"')}</div><div class="fd"><label for="info">Informations complémentaires <small>(facultatif)</small></label><textarea id="info" name="info" rows="3"></textarea></div>{CON}<button class="btn" type="submit">Envoyer ma candidature</button>{ST}</form></section>'''
page('conducteur','Devenir conducteur','Recevez une rémunération pour une publicité sur votre voiture, selon les conditions du programme ROAM.',D,'<script src="../conducteur.js"></script>')
L=f'''<section class="cand dm" aria-labelledby="de-t"><div class="cah"><p class="eye">Créer ma campagne</p><h1 class="big" id="de-t">Parlons de votre campagne</h1><p class="lead2">Dites-nous ce que vous voulez faire connaître et où. Nous revenons vers vous avec une proposition.</p><ul class="pts"><li>Création, pose, diffusion et suivi</li><li>Formats Classique, Medium ou Complet</li><li>Tarif sur devis</li></ul></div>
<form class="fm" data-form="quoteEndpoint" novalidate><div class="g2">{F('name','Nom et prénom')}{F('company','Entreprise')}{F('email','E-mail','email')}{F('phone','Téléphone','tel',False)}{F('zones','Villes ou zones visées')}<div class="fd"><label for="format">Format envisagé <small>(facultatif)</small></label><select id="format" name="format"><option value="">Je ne sais pas encore</option><option>Classique</option><option>Medium</option><option>Complet</option></select></div></div><div class="fd"><label for="message">Votre projet <small>(facultatif)</small></label><textarea id="message" name="message" rows="3"></textarea></div>{CON}<button class="btn" type="submit">Envoyer ma demande</button>{ST}</form></section>'''
page('demande','Créer ma campagne','Demandez une proposition pour votre campagne de publicité sur véhicules.',L,'<script>document.documentElement.classList.remove("mo")</script>')
